#!/usr/bin/env bash
# ============================================================================
#  GSZ step110 — product drag-to-reorder (#4). Reuses admin-sort.js from
#  step109; replaces the up/down arrows with a drag handle and persists order
#  via POST /products/reorder. Safe + idempotent; restores on any failure.
# ============================================================================
set -euo pipefail
GSZ=/opt/gsz
TS=$(date +%Y%m%d-%H%M%S)
BK="$GSZ/.bak-step110-$TS"
TMP=$(mktemp -d)
FILES=(routes/adminCatalog.js views/admin/products.ejs)

echo "==> step110: product drag-to-reorder"
if [ ! -f "$GSZ/public/js/admin-sort.js" ]; then echo "!!  admin-sort.js missing — run step109 first"; exit 1; fi
mkdir -p "$BK"
for f in "${FILES[@]}"; do mkdir -p "$BK/$(dirname "$f")"; cp "$GSZ/$f" "$BK/$f"; done
echo "    backup: $BK"

restore() {
  echo "!!  FAILED — restoring previous files"
  for f in "${FILES[@]}"; do cp "$BK/$f" "$GSZ/$f"; done
  pm2 restart gsz >/dev/null 2>&1 || true
  echo "!!  restored. no changes kept."
}
trap 'restore' ERR

echo "" | base64 -d > "$TMP/patch_step110.js"

echo "==> applying patch"
node "$TMP/patch_step110.js" "$GSZ"

echo "==> writing products.ejs"
echo "" | base64 -d > "$GSZ/views/admin/products.ejs"

echo "==> validating"
node --check "$GSZ/routes/adminCatalog.js"
node -e "const ejs=require('$GSZ/node_modules/ejs');ejs.compile(require('fs').readFileSync('$GSZ/views/admin/products.ejs','utf8'),{filename:'$GSZ/views/admin/products.ejs'});console.log('    products.ejs ok')"

echo "==> restarting app"
pm2 restart gsz >/dev/null 2>&1 || pm2 restart gsz
sleep 2

echo "==> health checks"
CODE=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3900/ || true)
[ "$CODE" = "200" ] && echo "    homepage 200: OK" || { echo "    homepage $CODE"; false; }
AC=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3900/admin/products || true)
[ "$AC" = "200" ] || [ "$AC" = "302" ] && echo "    /admin/products reachable ($AC): OK" || { echo "    /admin/products $AC"; false; }

trap - ERR
rm -rf "$TMP"
echo ""
echo "==> step110 OK ✅"
echo "    • Products list now has a drag handle — drag rows to reorder."
echo "    • Order saves instantly and is the order customers see on the storefront."
echo "    • Up/down arrows replaced by drag; everything else (bulk, trending, edit) unchanged."
